Customer Portal.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Customer Portal container

Container_Boundary(customer_portal, "Customer Portal") {
    Component(CustomerPortalSPA, "Customer Portal SPA", "React, TypeScript, Azure Static Web Apps", "Hosts the Single Page Application for fast global distribution and CI/CD integration, enabling customers and brokers to interact with and manage claims.")
    Component(AzureBlobStorage, "Azure Blob Storage", "Azure Blob Storage", "Stores uploaded claim documents securely via presigned URLs to offload binary payloads from the API gateway.")
    Component(ClaimsApiGateway, "Claims API Gateway", "HTTPS / REST (TLS 1.3, OAuth 2.0 / OIDC)", "Receives API requests from the Customer Portal.")
}

Rel(CustomerPortalSPA, ClaimsApiGateway, "Sends API requests", "HTTPS / REST (TLS 1.3, OAuth 2.0 / OIDC)")
Rel(CustomerPortalSPA, AzureBlobStorage, "Uploads documents securely via presigned URLs", "HTTPS")

@enduml

Claims API Gateway.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(claims_api_gateway, "Claims API Gateway") {
    Component(Edge Security Component, "Edge Security Component", "Azure API Management WAF & JWT Policy", "Handles edge security, WAF, and JWT validation.")
    Component(Authorization & Context Injection Component, "Authorization & Context Injection Component", "Azure API Management CBAC Policy", "Performs authorization and context injection using CBAC policies.")
    Component(Dynamic Routing & Transformation Component, "Dynamic Routing & Transformation Component", "Azure API Management Policy Engine", "Executes dynamic routing and request transformations.")
    Component(Resiliency Component, "Resiliency Component", "Azure API Management Circuit Breaker & Diagnostics", "Provides resiliency through circuit breakers and diagnostics.")
}

Rel(Edge Security Component, Authorization & Context Injection Component, "Passes authenticated requests")
Rel(Authorization & Context Injection Component, Dynamic Routing & Transformation Component, "Passes authorized context")
Rel(Dynamic Routing & Transformation Component, Resiliency Component, "Routes filtered traffic")

@enduml
